package com.moment.app;
import android.view.*;
import android.widget.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;

final class WeekCalendar {
 static void attach(MainActivity a,LinearLayout parent,List<CalendarItem> all,LocalDate selected){
  LocalDate first=TaskPlan.sunday(selected);parent.addView(InlineCalendar.text(a,InlineCalendar.dateLabel(first)+" – "+InlineCalendar.dateLabel(first.plusDays(6)),15,InlineCalendar.INK,true));
  boolean fit=a.getPreferences(0).getBoolean("fit_week",true);CheckBox fitControl=new CheckBox(a);fitControl.setText("Fit all 7 days");fitControl.setChecked(fit);fitControl.setOnCheckedChangeListener((v,on)->{a.getPreferences(0).edit().putBoolean("fit_week",on).apply();a.show();});parent.addView(fitControl);
  parent.addView(InlineCalendar.text(a,"Hold a block and drag to another time or day. Turn off Fit all 7 days for wider, scrollable columns.",12,InlineCalendar.MUTED,false),a.margins(4,7));
  HorizontalScrollView horizontal=new HorizontalScrollView(a);horizontal.setHorizontalScrollBarEnabled(true);LinearLayout grid=InlineCalendar.vertical(a);horizontal.addView(grid);parent.addView(horizontal);
  int gutter=a.dp(42),width=fit?Math.max(a.dp(30),(a.getResources().getDisplayMetrics().widthPixels-a.dp(50)-gutter)/7):a.dp(110);LinearLayout header=new LinearLayout(a);grid.addView(header);header.addView(InlineCalendar.text(a,"",11,InlineCalendar.MUTED,false),new LinearLayout.LayoutParams(gutter,a.dp(54)));
  LinearLayout allday=new LinearLayout(a);grid.addView(allday);allday.addView(InlineCalendar.text(a,"All day",10,InlineCalendar.MUTED,false),new LinearLayout.LayoutParams(gutter,a.dp(65)));
  ScrollView vertical=new ScrollView(a);vertical.setNestedScrollingEnabled(true);LinearLayout row=new LinearLayout(a);vertical.addView(row);grid.addView(vertical,new LinearLayout.LayoutParams(gutter+7*width,a.dp(450)));
  LinearLayout hours=InlineCalendar.vertical(a);row.addView(hours,new LinearLayout.LayoutParams(gutter,a.dp(1440)));for(int h=0;h<24;h++)hours.addView(InlineCalendar.text(a,LocalTime.of(h,0).format(DateTimeFormatter.ofPattern("ha",Locale.US)),11,InlineCalendar.MUTED,false),new LinearLayout.LayoutParams(-1,a.dp(60)));
  for(int d=0;d<7;d++){
   LocalDate date=first.plusDays(d);TextView label=InlineCalendar.text(a,date.format(DateTimeFormatter.ofPattern("EEE\nd",Locale.US)),fit?11:13,InlineCalendar.INK,true);label.setGravity(Gravity.CENTER);label.setBackground(InlineCalendar.round(a,date.equals(selected)?InlineCalendar.LAVENDER:InlineCalendar.BG,6));header.addView(label,new LinearLayout.LayoutParams(width,a.dp(54)));label.setOnClickListener(v->InlineCalendar.choose(a,date));CalendarDrag.target(a,label,date,null);
   List<CalendarItem> daily=InlineCalendar.day(all,date);LinearLayout untimed=InlineCalendar.vertical(a);allday.addView(untimed,new LinearLayout.LayoutParams(width,a.dp(65)));int count=0;for(CalendarItem item:daily)if(!item.timed()&&(!item.task()||!item.done)&&count++<2){TextView chip=InlineCalendar.text(a,item.title,11,InlineCalendar.INK,false);chip.setSingleLine(true);chip.setEllipsize(android.text.TextUtils.TruncateAt.END);chip.setPadding(a.dp(3),0,a.dp(3),0);chip.setBackground(InlineCalendar.round(a,InlineCalendar.color(item),5));untimed.addView(chip,new LinearLayout.LayoutParams(-1,a.dp(30)));chip.setOnClickListener(v->CalendarDrag.open(a,item));CalendarDrag.source(a,chip,item,false);}CalendarDrag.target(a,untimed,date,null);
   FrameLayout canvas=new FrameLayout(a);canvas.setTag("week-day-"+date);canvas.setBackgroundColor(d%2==0?0xfffaf8fd:0xffffffff);row.addView(canvas,new LinearLayout.LayoutParams(width,a.dp(1440)));CalendarDrag.target(a,canvas,date,0);
   for(int h=0;h<24;h++){final int hour=h;TextView slot=InlineCalendar.text(a,"",12,InlineCalendar.MUTED,false);FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(-1,a.dp(60));p.topMargin=a.dp(h*60);canvas.addView(slot,p);float[] y={0};slot.setOnTouchListener((v,e)->{if(e.getAction()==MotionEvent.ACTION_DOWN)y[0]=e.getY()/a.getResources().getDisplayMetrics().density;return false;});slot.setOnClickListener(v->{int minute=TaskPlan.snap(hour*60+Math.round(y[0]),30);EventEditor.create(a,date,LocalTime.of(minute/60,minute%60));});slot.setContentDescription("Add event, "+InlineCalendar.dateLabel(date)+", "+EventEditor.label(LocalTime.of(h,0)));View rule=new View(a);rule.setBackgroundColor(0xffe8e3ef);FrameLayout.LayoutParams r=new FrameLayout.LayoutParams(-1,a.dp(1));r.topMargin=p.topMargin;canvas.addView(rule,r);}
   for(CalendarMath.Block block:CalendarMath.layout(daily)){CalendarItem item=block.item;TextView chip=InlineCalendar.text(a,item.title+"\n"+EventEditor.label(LocalTime.parse(item.time))+"\n"+item.category,11,InlineCalendar.INK,true);chip.setPadding(a.dp(4),a.dp(2),a.dp(3),a.dp(2));chip.setMaxLines(Math.max(1,item.duration/20));chip.setEllipsize(android.text.TextUtils.TruncateAt.END);chip.setBackground(InlineCalendar.round(a,InlineCalendar.color(item),7));FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(Math.max(a.dp(20),width/block.lanes-a.dp(3)),a.dp(Math.max(30,item.duration)-2));p.leftMargin=block.lane*width/block.lanes+a.dp(1);p.topMargin=a.dp(item.start());canvas.addView(chip,p);chip.setContentDescription(item.title+", "+InlineCalendar.dateLabel(date)+", "+EventEditor.label(LocalTime.parse(item.time))+", "+item.duration+" minutes. Hold to drag.");chip.setOnClickListener(v->CalendarDrag.open(a,item));CalendarDrag.source(a,chip,item,true);}
   if(date.equals(LocalDate.now()))InlineCalendar.liveNow(a,canvas,date,0,1440);
  }
  boolean anyUntimed=false;for(CalendarItem item:all)if(!item.timed()&&(!item.task()||!item.done))for(int d=0;d<7;d++)if(item.on(first.plusDays(d)))anyUntimed=true;if(!anyUntimed)allday.setVisibility(View.GONE);
  grid.setTag("week_calendar_ready");vertical.post(()->vertical.scrollTo(0,a.dp(8*60)));
 }
}
